from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parent
MODULE_PATH = ROOT / "qseries_v2" / "integration" / "qseries_execution_readiness_gate.py"
TEST_PATH = ROOT / "test_int_014_qseries_execution_readiness_gate.py"
INIT_PATH = ROOT / "qseries_v2" / "integration" / "__init__.py"

MODULE_CODE_B64 = ""
TEST_CODE_B64 = ""

EXPORT_NAMES = '''    "QSERIES_EXECUTION_READINESS_SCHEMA_VERSION",
    "QSERIES_EXECUTION_READINESS_ENGINE_ID",
    "QSERIES_EXECUTION_READINESS_READ_ONLY",
    "QSERIES_EXECUTION_READINESS_EXECUTION_ALLOWED",
    "FINAL_EXECUTION_GATE_REQUIRED",
    "ExecutionReadinessStatus",
    "ExecutionReadinessLimits",
    "ExecutionReadinessRecord",
    "ExecutionReadinessCheck",
    "QSeriesExecutionReadinessResult",
    "review_execution_readiness",
    "validate_qseries_execution_readiness_result",

'''

EXPORT_IMPORT = '''from .qseries_execution_readiness_gate import (
    SCHEMA_VERSION as QSERIES_EXECUTION_READINESS_SCHEMA_VERSION,
    ENGINE_ID as QSERIES_EXECUTION_READINESS_ENGINE_ID,
    READ_ONLY as QSERIES_EXECUTION_READINESS_READ_ONLY,
    EXECUTION_ALLOWED as QSERIES_EXECUTION_READINESS_EXECUTION_ALLOWED,
    FINAL_EXECUTION_GATE_REQUIRED,
    ExecutionReadinessStatus,
    ExecutionReadinessLimits,
    ExecutionReadinessRecord,
    ExecutionReadinessCheck,
    QSeriesExecutionReadinessResult,
    review_execution_readiness,
    validate_qseries_execution_readiness_result,
)
'''


def _decode(payload: str) -> str:
    return base64.b64decode(payload.encode("ascii")).decode("utf-8-sig")


def _write_if_changed(path: Path, content: str) -> bool:
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_text(encoding="utf-8-sig") == content:
        return False
    path.write_text(content, encoding="utf-8")
    return True


def _update_init() -> bool:
    text = INIT_PATH.read_text(encoding="utf-8-sig") if INIT_PATH.exists() else ""
    original = text
    if "QSERIES_EXECUTION_READINESS_SCHEMA_VERSION" not in text:
        text = text.replace("__all__ = [\n", "__all__ = [\n" + EXPORT_NAMES, 1)
        if text == original:
            text += "\n__all__ = [\n" + EXPORT_NAMES.rstrip() + "\n]\n"
    if "qseries_execution_readiness_gate" not in text:
        text = text.rstrip() + "\n" + EXPORT_IMPORT
    if text == original:
        return False
    INIT_PATH.write_text(text, encoding="utf-8")
    return True


def main() -> None:
    changed = []
    if _write_if_changed(MODULE_PATH, _decode(MODULE_CODE_B64)):
        changed.append(str(MODULE_PATH.relative_to(ROOT)))
    if _write_if_changed(TEST_PATH, _decode(TEST_CODE_B64)):
        changed.append(str(TEST_PATH.relative_to(ROOT)))
    if _update_init():
        changed.append(str(INIT_PATH.relative_to(ROOT)))
    if changed:
        print("[WRITE] INT-014 Q Series Execution Readiness Gate")
        for path in changed:
            print(f" - {path}")
    else:
        print("[OK] INT-014 installer idempotent; no file changes required.")


if __name__ == "__main__":
    main()
